{
  "root_causes": [
    {
      "service": "shipping",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "log",
          "sql": "SELECT service_name, message, count(*) AS n FROM abnormal_logs WHERE service_name = 'shipping' AND message LIKE 'SIGTERM%' GROUP BY ALL",
          "claim": "Shipping received SIGTERM and began graceful shutdown at 09:19:50; no later shipping logs appear in the incident window."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' AS period, count(*) AS shipping_spans FROM abnormal_traces WHERE service_name = 'shipping' UNION ALL SELECT 'normal', count(*) FROM normal_traces WHERE service_name = 'shipping'",
          "claim": "Shipping emits zero spans in the incident window versus six in the normal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code = 'Error' THEN 1 ELSE 0 END) AS errors, round(avg(duration)/1e6, 2) AS avg_ms FROM abnormal_traces WHERE service_name = 'checkout' AND span_name = 'HTTP POST' GROUP BY ALL",
          "claim": "All 9 checkout outbound HTTP POST calls to shipping's endpoints fail with Error status after shutdown; none succeed."
        }
      ]
    },
    {
      "service": "frontend",
      "fault_kind": "dns_lookup_failed",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code = 'Error' THEN 1 ELSE 0 END) AS errors, round(avg(duration)/1e6, 3) AS avg_ms FROM abnormal_traces WHERE service_name = 'frontend' AND (span_name = 'dns.lookup' OR span_name LIKE 'grpc.oteldemo.ProductReviewService/%') GROUP BY ALL",
          "claim": "Frontend dns.lookup spans fail, and all ProductReviewService gRPC calls fail in about 0.34 ms, consistent with no connection attempted."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) AS n, sum(CASE WHEN attr_status_code = 'Error' THEN 1 ELSE 0 END) AS errors FROM abnormal_traces WHERE service_name = 'frontend' AND span_name IN ('GET /api/product-reviews/[productId]/index', 'POST /api/product-ask-ai-assistant/[productId]/index') GROUP BY ALL",
          "claim": "Every product-reviews and product-ask-ai-assistant request through frontend returns HTTP 500 in the incident window."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "shipping",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code = 'Error' THEN 1 ELSE 0 END) AS errors FROM abnormal_traces WHERE service_name = 'checkout' AND (span_name = 'HTTP POST' OR span_name LIKE '%PlaceOrder%') GROUP BY ALL",
          "claim": "Checkout's HTTP POST calls fail and its PlaceOrder server spans error out, 9 of 9 each."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_status_code = 'Error' THEN 1 ELSE 0 END) AS errors FROM abnormal_traces WHERE span_name IN ('POST /api/checkout', 'grpc.oteldemo.CheckoutService/PlaceOrder') GROUP BY ALL",
          "claim": "Frontend's POST /api/checkout and its PlaceOrder gRPC client calls error in the same traces as checkout failures."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, sum(CASE WHEN attr_http_response_status_code = 500 THEN 1 ELSE 0 END) AS http_500 FROM abnormal_traces WHERE service_name = 'frontend-proxy' AND attr_span_kind = 'Server' GROUP BY ALL",
          "claim": "Frontend-proxy ingress returns 500 for 26 requests, matching the frontend checkout, review and AI-assistant failures."
        }
      ]
    }
  ]
}
